// Generic async retry helper.
//
// Options:
//   retries      number of retries AFTER the first attempt (default 3)
//   baseDelayMs  delay before the first retry (default 100)
//   factor       exponential backoff multiplier (default 2)
//   sleep        (ms, signal) => Promise, injectable for tests
//   signal       optional AbortSignal; aborting cancels further attempts
//
// fn receives the zero-based attempt index.

export function defaultSleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(signal.reason);
      return;
    }
    const t = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(t);
      reject(signal.reason);
    };
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

export async function retry(fn, opts = {}) {
  const { retries = 3, baseDelayMs = 100, factor = 2, sleep = defaultSleep, signal } = opts;

  if (signal?.aborted) {
    throw signal.reason;
  }

  let lastErr;
  for (let attempt = 0; attempt <= retries; attempt++) {
    if (signal?.aborted) {
      throw signal.reason;
    }
    try {
      return await fn(attempt);
    } catch (err) {
      lastErr = err;
      if (err.retryable === false) {
        throw err;
      }
      if (signal?.aborted) {
        throw signal.reason;
      }
      if (attempt === retries) {
        break;
      }
      const delay = baseDelayMs * Math.pow(factor, attempt);
      try {
        if (signal) {
          // Race sleep against abort to guarantee immediate abort even if
          // the injected sleep ignores the signal.
          let abortHandler;
          const abortPromise = new Promise((_, reject) => {
            abortHandler = () => reject(signal.reason);
            signal.addEventListener('abort', abortHandler, { once: true });
          });
          try {
            await Promise.race([sleep(delay, signal), abortPromise]);
          } catch (e) {
            signal.removeEventListener('abort', abortHandler);
            if (signal.aborted) {
              throw signal.reason;
            }
            throw e;
          }
          signal.removeEventListener('abort', abortHandler);
        } else {
          await sleep(delay, signal);
        }
      } catch (sleepErr) {
        if (signal?.aborted) {
          throw signal.reason;
        }
        throw sleepErr;
      }
    }
  }
  throw lastErr;
}

