// Rounding helpers for integer-cent money math.

/**
 * Round a cent amount half-up (2.5 -> 3, -2.5 -> -2), i.e. Math.round semantics.
 * Used by: invoice.mjs (line tax), statement.mjs (late fees - half-up is
 * written into the customer agreement, do not change for statements).
 */
export function roundCents(x) {
  return Math.round(x);
}

/**
 * Banker's rounding (round half to even).
 * 2.5 -> 2, 3.5 -> 4, -2.5 -> -2, -3.5 -> -4.
 * For non-half values, rounds to nearest.
 */
export function roundHalfEven(x) {
  if (!Number.isFinite(x)) return Math.round(x);
  if (x === 0) return 0;
  const sign = x < 0 ? -1 : 1;
  const absX = Math.abs(x);
  const floor = Math.floor(absX);
  const frac = absX - floor;
  const EPS = 1e-12;
  if (Math.abs(frac - 0.5) < EPS) {
    return sign * (floor % 2 === 0 ? floor : floor + 1);
  }
  return sign * (frac < 0.5 ? floor : floor + 1);
}

/**
 * Exact banker's rounding for integer division n/d (d > 0).
 * Returns nearest integer to n/d, ties to even, symmetric for negatives.
 */
export function roundDivHalfEven(n, d) {
  if (!Number.isInteger(d) || d <= 0) throw new RangeError('denominator must be positive integer');
  if (n === 0) return 0;
  const sign = n < 0 ? -1 : 1;
  const absN = Math.abs(n);
  const q = Math.trunc(absN / d);
  const r = absN % d;
  const twiceR = r * 2;
  let rounded;
  if (twiceR < d) rounded = q;
  else if (twiceR > d) rounded = q + 1;
  else {
    rounded = q % 2 === 0 ? q : q + 1;
  }
  return sign * rounded;
}

