/**
 * Banker's rounding for tax: round (netCents * taxBps / 10000) half to even, symmetric.
 * Uses integer arithmetic to detect exact halves without floating error.
 */
function bankersRoundTax(netCents, taxBps) {
  if (Number.isInteger(netCents)) {
    const numerator = netCents * taxBps;
    const absNum = Math.abs(numerator);
    const q = Math.trunc(absNum / 10000);
    const r = absNum % 10000;
    let roundedAbs;
    if (r < 5000) {
      roundedAbs = q;
    } else if (r > 5000) {
      roundedAbs = q + 1;
    } else {
      // exactly half
      roundedAbs = (q % 2 === 0) ? q : q + 1;
    }
    return numerator < 0 ? -roundedAbs : roundedAbs;
  } else {
    // Fallback for non-integer netCents (should not happen in normal use)
    const x = (netCents * taxBps) / 10000;
    if (x === 0) return 0;
    const abs = Math.abs(x);
    const floor = Math.floor(abs);
    const frac = abs - floor;
    let roundedAbs;
    if (frac < 0.5) roundedAbs = floor;
    else if (frac > 0.5) roundedAbs = floor + 1;
    else roundedAbs = (floor % 2 === 0) ? floor : floor + 1;
    return x < 0 ? -roundedAbs : roundedAbs;
  }
}

/**
 * @param {Array<{ sku: string, qty: number, unitCents: number }>} lines
 * @param {{ taxBps: number }} opts  tax rate in basis points (2000 = 20%)
 */
export function buildInvoice(lines, { taxBps }) {
  if (!Number.isInteger(taxBps) || taxBps < 0) throw new RangeError('taxBps must be a non-negative integer');
  const out = lines.map((l) => {
    const netCents = l.qty * l.unitCents;
    const taxCents = bankersRoundTax(netCents, taxBps);
    return { sku: l.sku, qty: l.qty, unitCents: l.unitCents, netCents, taxCents };
  });
  const subtotalCents = out.reduce((s, l) => s + l.netCents, 0);
  const taxCents = out.reduce((s, l) => s + l.taxCents, 0);
  return { lines: out, subtotalCents, taxCents, totalCents: subtotalCents + taxCents, taxBps };
}

